// JS Map preserves insertion order; re-inserting a key moves it to "most recent".
class LRU {
  constructor(capacity) { this.cap = capacity; this.map = new Map(); this.hits = 0; this.misses = 0; }
  get(key) {
    if (!this.map.has(key)) { this.misses++; return undefined; }
    const val = this.map.get(key);
    this.map.delete(key); this.map.set(key, val);   // touch → most recent
    this.hits++; return val;
  }
  put(key, val) {
    if (this.map.has(key)) this.map.delete(key);
    else if (this.map.size >= this.cap) this.map.delete(this.map.keys().next().value); // evict LRU
    this.map.set(key, val);
  }
  hitRate() { const t = this.hits + this.misses; return t ? this.hits / t : 0; }
}

