// dependents[X] = components that fail if X fails.
function blastRadius(dependents, failed) {
  const down = new Set([failed]);
  const stack = [failed];
  while (stack.length) {
    const node = stack.pop();
    for (const dep of (dependents[node] || [])) {
      if (!down.has(dep)) { down.add(dep); stack.push(dep); }   // propagate to dependents
    }
  }
  return down;
}
// A bulkhead makes a dependency optional → remove that edge before propagating.
function withBulkhead(dependents, from, to) {
  const copy = {}; for (const k in dependents) copy[k] = dependents[k].filter(d => !(k === from && d === to));
  return copy;
}

