class CircuitBreaker {
  constructor(threshold, cooldownMs) {
    this.state = "closed"; this.failures = 0; this.threshold = threshold;
    this.cooldownMs = cooldownMs; this.openedAt = 0;
  }
  onResult(ok, now) {
    if (this.state === "open" && now - this.openedAt >= this.cooldownMs) this.state = "half-open"; // cooldown → probe
    if (this.state === "half-open") {
      this.state = ok ? "closed" : "open";          // trial closes or re-opens
      if (this.state === "closed") this.failures = 0; else this.openedAt = now;
      return this.state;
    }
    if (ok) { this.failures = 0; }
    else if (++this.failures >= this.threshold) { this.state = "open"; this.openedAt = now; } // trip
    return this.state;
  }
}

