// SLO over a window → error budget (allowed bad time), then how fast you're burning it.
function errorBudget(sloFraction, windowMinutes) {
  return (1 - sloFraction) * windowMinutes;   // e.g. 0.001 * 43200 = 43.2 min allowed
}
function burnRate(actualBadMinutes, elapsedMinutes, sloFraction) {
  // 1x burn spends the budget exactly over the window; >1x is too fast.
  const allowedFractionOfTime = 1 - sloFraction;
  const actualFractionOfTime = actualBadMinutes / elapsedMinutes;
  return actualFractionOfTime / allowedFractionOfTime;
}

