class TokenBucket {
  constructor(capacity, refillPerSec) {
    this.capacity = capacity; this.tokens = capacity;   // start full
    this.refillPerSec = refillPerSec; this.last = 0;
  }
  tryAdmit(now) {                                        // now in seconds
    const elapsed = now - this.last; this.last = now;
    this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillPerSec); // lazy refill
    if (this.tokens >= 1) { this.tokens -= 1; return true; }  // spend a token → admit
    return false;                                             // empty → reject
  }
}

