const METHOD = ["frame", "estimate", "high-level", "deep-dive", "bottleneck", "tradeoff"];
// Check a design transcript walked all steps in the canonical order.
function checkMethod(stepsTaken) {
  const missing = METHOD.filter(s => !stepsTaken.includes(s));
  // order check: the taken steps, filtered to method steps, must match canonical order
  const seq = stepsTaken.filter(s => METHOD.includes(s));
  const canonical = METHOD.filter(s => seq.includes(s));
  const inOrder = seq.join(",") === canonical.join(",");
  return { complete: missing.length === 0, missing, inOrder };
}

